#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 0x400  // 1024 characters

int main(int argc, char **argv) {
    const char *input;
    char out[MAX_LEN + 1]; // +1 for terminating NUL
    size_t out_len = 0;
    size_t i, len;
    int have_word = 0; // whether we have already written a word (used for leading space handling)
    int prev_was_space = 0;

    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    input = argv[1];
    len = strlen(input);
    if (len > MAX_LEN) len = MAX_LEN; // truncate to 1024 characters as the original does

    // Skip leading whitespace (the original logic does this implicitly by not emitting a space before the first word)
    for (i = 0; i < len; ++i) {
        char c = input[i];
        // treat only the standard C whitespace characters that the original checks for
        int is_ws = (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f');
        if (is_ws) {
            // remember that we have seen whitespace, but do not output anything yet
            prev_was_space = 1;
            continue;
        }
        // non‑whitespace character
        if (prev_was_space && have_word) {
            // we are after some whitespace and already have output before – insert a single space
            out[out_len++] = ' ';
        }
        out[out_len++] = c;
        have_word = 1;
        prev_was_space = 0;
    }

    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
